#!/usr/bin/env bash
set -Eeuo pipefail

# AgentWorker: publish the pod-provided per-pod env the guest launcher fetches
# over nginx at http://host.lan:8090/env. The guest does NOT inherit the pod's
# env, so WORKER_TOKEN (pre-auth) + SANDBOX_PROXY (deployment HTTP proxy for the
# guest's jobs) travel here.
{
  printf 'WORKER_TOKEN=%s\n' "${WORKER_TOKEN:-}"
  printf 'SANDBOX_PROXY=%s\n' "${SANDBOX_PROXY:-${HTTP_PROXY:-}}"
} > /run/shm/env
chmod 644 /run/shm/env 2>/dev/null || true

# The UEFI firmware is generated by the boot scripts from the base image's
# /usr/share/OVMF (OVMF_CODE_4M.fd + OVMF_VARS_4M.fd), NOT shipped here. Do not
# pre-seed a ROM on the PVC: a mismatched/size-wrong one makes QEMU refuse to
# start ("combined size of system firmware exceeds 8388608 bytes").
# Drop any firmware an EARLIER image left on the persistent PVC so boot.sh
# regenerates a correct 4M one (the OVMF build is image-owned, not disk state).
rm -f /storage/windows.rom /storage/windows.vars \
      /storage/uefi.rom /storage/uefi.vars \
      /storage/secure.rom /storage/secure.vars 2>/dev/null || true

# Materialize the guest disk from the artifact-published golden base (overlay);
# a no-op when GOLDEN_DISK_URL is unset (image-embedded disk is used).
if [ -f /run/golden-disk.sh ]; then . /run/golden-disk.sh; fi

return 0
